func TestComposeReviewPrompt_ScopeIncludesUncommittedChanges(t *testing.T) {
	t.Parallel()
	cfg := reviewtypes.RunConfig{
		Skills:       []string{"/x"},
		ScopeBaseRef: "origin/main",
	}
	got := ComposeReviewPrompt(cfg)
