func TestReviewer_ArgvIncludesReadOnlyAllowlist(t *testing.T) {
	t.Parallel()
	cmd := buildReviewCmd(context.Background(), reviewtypes.RunConfig{Skills: []string{"/x"}})

	allowed := ""
	for i, arg := range cmd.Args {
		if arg == "--allowedTools" && i+1 < len(cmd.Args) {
